func main() {
    var count atomic.Int64
    var wg sync.WaitGroup
    wg.Add(2)
    for worker := 0; worker < 2; worker++ {
        go func() { defer wg.Done(); for i := 0; i < 100; i++ { count.Add(1) } }()
    }
    wg.Wait()
    fmt.Println(count.Load())
}

